  assert.equal((await request("DELETE", "/blobs/del%2Fcaf%C3%A9%2Fmenu.txt")).status, 204);
  assert.equal((await request("GET", "/blobs/del/caf%C3%A9/menu.txt")).status, 404);
});

it("DELETE answers 404 for keys that are not blobs and leaves other blobs alone", async () => {
  assert.equal((await request("PUT", "/blobs/del/dir/file.txt", "keep")).status, 201);
  for (const path of [
    "/blobs/del/missing",
    "/blobs/no/such/dir/file",
    "/blobs/del/dir", // a directory of another key, not a blob
    "/blobs/del/dir/file.txt/child", // a path below an existing blob
    `/blobs/${"a/".repeat(2100)}a`, // longer than the file system allows
  ]) {
    const res = await request("DELETE", path);
    assert.equal(res.status, 404, path.slice(0, 60));
  }
  assert.equal((await request("GET", "/blobs/del/dir/file.txt")).body, "keep");
});

it("DELETE answers 400 for invalid keys and removes nothing", async () => {
  await writeFile(join(root, "outside"), "x");
  assert.equal((await request("PUT", "/blobs/del/inside", "x")).status, 201);
  const before = await readdir(root);
  for (const path of [
    "/blobs/",
    "/blobs/../outside",
    "/blobs/del/../../outside",
    "/blobs/%2e%2e/outside",
    "/blobs/%2E%2E%2Foutside",
    "/blobs//etc/passwd",
    "/blobs/%2Fetc%2Fpasswd",
    "/blobs/del//inside",
    "/blobs/del/inside/",
    "/blobs/./del/inside",
    "/blobs/%00",
    "/blobs/%",
    "/blobs/%zz",
    "/blobs/%FF",
    "/blobs/%ED%A0%80",
    `/blobs/${"a".repeat(256)}`,
  ]) {
    const res = await request("DELETE", path);
    assert.equal(res.status, 400, path);
  }
  assert.equal(await rawStatus("DELETE", Buffer.concat([Buffer.from("/blobs/"), Buffer.from([0xff, 0xfe])])), 400);
  assert.deepEqual(await readdir(root), before);
  assert.equal((await request("GET", "/blobs/del/inside")).status, 200);
});

it("DELETE prunes directories it leaves empty, so their names can become keys", async () => {
  assert.equal((await request("PUT", "/blobs/prune/a/b/c.txt", "x")).status, 201);
  assert.equal((await request("PUT", "/blobs/prune/sibling", "x")).status, 201);
  assert.equal((await request("DELETE", "/blobs/prune/a/b/c.txt")).status, 204);
  assert.deepEqual(await readdir(join(dataDir, "blobs", "prune")), ["sibling"]);
  assert.equal((await request("PUT", "/blobs/prune/a", "now a file")).status, 201);
  assert.equal((await request("GET", "/blobs/prune/a")).body, "now a file");
  assert.equal((await request("GET", "/blobs/prune/sibling")).status, 200);
});

it("GET, PUT and DELETE answer within the contract for arbitrary keys", async () => {
  const check = async (method: string, key: string, body?: string): Promise<number> => {
    const res = await request(method, `/blobs/${key}`, body);
    assert.ok(DECLARED_STATUSES[method]!.includes(res.status), `${method} /blobs/${key} -> ${res.status}`);
    return res.status;
  };
  for (const key of arbitraryKeys(54321, 300)) {
    // Missing (or invalid) keys first, then the full lifecycle.
    await check("GET", key);
    await check("DELETE", key);
    const put = await check("PUT", key, "x");
    const get = await check("GET", key);
    const del = await check("DELETE", key);
    if (put === 201) {
      assert.equal(get, 200, key);
      assert.equal(del, 204, key);
      assert.equal(await check("GET", key), 404, key);
    }
  }
  assert.equal((await request("GET", "/healthz")).status, 200);
});

it("PUTs stay successful while DELETEs prune the same directories", async () => {
  const rounds = 30;
  const results = await Promise.all(
    Array.from({ length: rounds }, async (_, i) => {
      const put = await request("PUT", `/blobs/race/dir/${i}`, `v${i}`);
      const del = await request("DELETE", `/blobs/race/dir/${i}`);
      const again = await request("PUT", `/blobs/race/dir/sub/${i}`, `w${i}`);
      return [put.status, del.status, again.status];
    }),
  );
  for (const statuses of results) assert.deepEqual(statuses, [201, 204, 201]);
  for (let i = 0; i < rounds; i++) {
    assert.equal((await request("GET", `/blobs/race/dir/sub/${i}`)).body, `w${i}`);
  }
});
